+import { readFileSync } from 'node:fs';
+import { fileURLToPath } from 'node:url';
+import path from 'node:path';
+
+const __dirname = path.dirname(fileURLToPath(import.meta.url));
+const rows = JSON.parse(readFileSync(path.join(__dirname, 'rows.json'), 'utf8'));
+
+const ALLOWED_ARGS = new Set(['limit', 'cursor']);
+
+function invalidCursor(message) {
+  const err = new Error(message);
+  err.code = 'INVALID_CURSOR';
+  return err;
+}
+
+function encodeCursor(offset) {
+  return Buffer.from(JSON.stringify({ o: offset })).toString('base64');
+}
+
+function decodeCursor(cursor) {
+  let parsed;
+  try {
+    const json = Buffer.from(cursor, 'base64').toString('utf8');
+    parsed = JSON.parse(json);
+  } catch {
+    throw invalidCursor('invalid cursor');
+  }
+  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
+    throw invalidCursor('invalid cursor');
+  }
+  if (!Number.isInteger(parsed.o) || parsed.o < 0) {
+    throw invalidCursor('invalid cursor');
+  }
+  return parsed.o;
+}
+
+export async function listTools() {
+  return [
+    {
+      name: 'page',
+      description: 'Page over rows.json, returning rows and a next_cursor.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          limit: { type: 'integer', minimum: 1, maximum: 2 },
+          cursor: { type: 'string' },
+        },
+        required: ['limit'],
+        additionalProperties: false,
+      },
+    },
+  ];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'page') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Invalid arguments');
+  }
+  for (const key of Object.keys(args)) {
+    if (!ALLOWED_ARGS.has(key)) {
+      throw new Error(`Unknown argument: ${key}`);
+    }
+  }
+  if (!('limit' in args)) {
+    throw new Error('limit is required');
+  }
+  const limit = args.limit;
+  if (!Number.isInteger(limit) || limit < 1 || limit > 2) {
+    throw new Error('limit must be an integer between 1 and 2');
+  }
+
+  let offset = 0;
+  if (args.cursor !== undefined) {
+    if (typeof args.cursor !== 'string') {
+      throw new Error('cursor must be a string');
+    }
+    offset = decodeCursor(args.cursor);
+    if (offset > rows.length) {
+      throw invalidCursor('stale cursor');
+    }
+  }
+
+  const slice = rows.slice(offset, offset + limit);
+  const nextOffset = offset + limit;
+  const next_cursor = nextOffset < rows.length ? encodeCursor(nextOffset) : null;
+  return { rows: slice, next_cursor };
+}
